'use strict';
// Visual edition 04: a local, reviewable social-detox experience.
const viralGroups=[['Pause, play & share',[
 ['companion','Meet your companion','A living sprout that grows with thoughtful decisions.'],
 ['temptation-counter','Your temptation counter','Parked wants, recorded skips and real savings stay distinct.'],
 ['capture-guide','Save from anywhere','Preview native sharing; paste a link in the browser.'],
 ['battle-hub','No-Buy Battles','Private challenges measured by showing up, not wealth.'],
 ['battle-create','Create a battle','Choose a duration, category and essential exception.'],
 ['battle-lobby','Your battle room','Local check-ins and a clearly labeled demo opponent.'],
 ['battle-results','Battle recap','Review the challenge without resetting progress.'],
 ['anti-haul','Your monthly anti-haul','A private list of recorded wants you let go.'],
 ['achievements','Your achievements','Celebrate estimated savings, skipped wants and honest check-ins.']
]]];
let counterPeriod='month';
function migrateViral(data){
 for(const [k,v] of Object.entries({skippedWants:[],decisionEvents:[],viralCheckins:{},battle:null,shareStyle:'forest'}))if(data[k]===undefined)data[k]=structuredClone(v);
 if(data.skippedBaseline===undefined)data.skippedBaseline=Number(data.skipped)||0;
 return data;
}
function localDateKey(value=Date.now()){const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function recordedSkips(period='month'){const prefix=localDateKey().slice(0,7);return state.skippedWants.filter(x=>period==='all'||localDateKey(x.date).startsWith(prefix));}
function skipTotal(period='month'){return recordedSkips(period).reduce((n,x)=>n+x.price,0);}
function recordDecision(w,choice){if(!w?.id||state.decisionEvents.some(x=>x.itemId===w.id))return;state.decisionEvents.push({itemId:w.id,choice,date:new Date().toISOString(),completedWait:new Date(w.cooldownUntil).getTime()<=Date.now()});}
function recordSkippedWant(w){if(state.skippedWants.some(x=>x.itemId===w.id))return;const before=new Set(achievementDefinitions().filter(a=>a.value>=a.goal).map(a=>a.id));state.skippedWants.push({itemId:w.id,name:w.name,price:w.price,category:w.category,icon:w.icon,date:new Date().toISOString()});recordDecision(w,'Skipped');draft.earnedAchievements=achievementDefinitions().filter(a=>a.value>=a.goal&&!before.has(a.id)).map(a=>a.title);}
function recordViralCheckin(){state.viralCheckins[localDateKey()]={date:new Date().toISOString()};}
function companionProgress(){const n=state.decisionEvents.length+Object.keys(state.viralCheckins).length+(state.pauseEvents?.length||0);return {n,stage:n>=12?2:n>=4?1:0,name:n>=12?'In bloom':n>=4?'Finding your rhythm':'A fresh start',next:n>=12?null:n>=4?12:4};}
function achievementDefinitions(){const skips=recordedSkips('all').length,savings=skipTotal('all'),days=Object.keys(state.viralCheckins).length;return [
 {id:'first-skip',title:'First little win',description:'Let your first saved want go.',value:skips,goal:1,unit:'purchase',icon:'leaf'},
 {id:'five-skips',title:'Impulse interrupter',description:'Reconsider five purchases.',value:skips,goal:5,unit:'purchases',icon:'pause'},
 {id:'ten-skips',title:'Room to breathe',description:'Let ten saved wants go.',value:skips,goal:10,unit:'purchases',icon:'heart'},
 {id:'savings-100',title:'A little freedom',description:money(100)+' in estimated savings.',value:savings,goal:100,unit:'money',icon:'wallet'},
 {id:'savings-500',title:'Making room',description:money(500)+' in estimated savings.',value:savings,goal:500,unit:'money',icon:'spark'},
 {id:'savings-1000',title:'Intentional spender',description:money(1000)+' in estimated savings.',value:savings,goal:1000,unit:'money',icon:'flag'},
 {id:'seven-checkins',title:'Showing up',description:'Record seven honest check-in days.',value:days,goal:7,unit:'days',icon:'sun'}
 ];}
function achievementPreview(){const all=achievementDefinitions(),earned=all.filter(a=>a.value>=a.goal),next=all.find(a=>a.value<a.goal);return `<button class="achievement-preview" data-go="achievements"><span class="achievement-medal">${icon(earned.length?'spark':'leaf')}</span><span><span class="overline">${earned.length} / ${all.length} ACHIEVEMENTS</span><strong>${earned.at(-1)?.title||'Your first little win awaits'}</strong><small>${next?next.description:'Look at the room you made.'}</small></span>${icon('chevron')}</button>`;}
function savingsHero(){return `<section class="savings-hero"><div class="row between"><span class="overline">SAVINGS</span><span class="savings-pill">${icon('leaf')} From skipped purchases</span></div><strong>${money(state.skipped)}</strong><p>Estimated spending you chose to avoid.</p>${state.skippedBaseline>0?'<small>Includes earlier prototype demo history.</small>':''}<div class="savings-footer"><button data-go="anti-haul">${money(skipTotal())} this month ${icon('arrow')}</button><button data-go="achievements">My achievements ${icon('spark')}</button></div></section>`;}
function achievementCards(){return achievementDefinitions().map(a=>{const earned=a.value>=a.goal;return `<article class="achievement-card ${earned?'unlocked':'locked'}"><span class="achievement-medal">${icon(earned?a.icon:'lock')}</span><span class="achievement-status">${earned?'UNLOCKED':'IN PROGRESS'}</span><h2>${a.title}</h2><p>${a.description}</p>${progress(a.value/a.goal*100)}<small>${a.unit==='money'?money(Math.min(a.value,a.goal))+' / '+money(a.goal):Math.min(a.value,a.goal)+' / '+a.goal+' '+a.unit}</small></article>`;}).join('');}
function mascot(stage=companionProgress().stage,cls=''){
 return `<div class="sprout-mascot stage-${stage} ${cls}" role="img" aria-label="Smiling sprout companion, growth stage ${stage+1} of 3"><svg viewBox="0 0 260 250" xmlns="http://www.w3.org/2000/svg"><ellipse class="sprout-shadow" cx="130" cy="227" rx="70" ry="10" fill="#183f35" opacity=".1"/><g class="sprout-body"><path class="sprout-arm left" d="M65 161Q30 143 36 132" fill="none" stroke="#9acb6c" stroke-width="17" stroke-linecap="round"/><path class="sprout-arm right" d="M195 158Q225 138 216 126" fill="none" stroke="#9acb6c" stroke-width="17" stroke-linecap="round"/><path d="M93 211v12m70-12v12" stroke="#638e45" stroke-width="14" stroke-linecap="round"/><path d="M61 156c0-51 27-79 69-79s70 29 70 79c0 41-30 63-70 63s-69-22-69-63Z" fill="#bfdf8d"/><path d="M79 126c7-22 19-31 32-33" fill="none" stroke="#f7ffdd" stroke-width="9" stroke-linecap="round" opacity=".65"/><g class="sprout-leaves"><path d="M130 87V57" stroke="#4e8651" stroke-width="9" stroke-linecap="round"/><path d="M130 70C83 76 76 34 76 34c42-9 58 20 54 36Z" fill="#74b56f"/><path d="M130 61c45 2 58-39 58-39-43-10-61 18-58 39Z" fill="#3e825b"/></g><g class="sprout-eyes"><ellipse cx="105" cy="148" rx="6" ry="8" fill="#183f35"/><ellipse cx="155" cy="148" rx="6" ry="8" fill="#183f35"/></g><ellipse cx="90" cy="165" rx="13" ry="7" fill="#f3ad91" opacity=".7"/><ellipse cx="170" cy="165" rx="13" ry="7" fill="#f3ad91" opacity=".7"/><path d="M119 164q11 15 22 0" fill="none" stroke="#183f35" stroke-width="4" stroke-linecap="round"/>${stage===2?'<g class="sprout-flower"><circle cx="185" cy="48" r="19" fill="#f3ad91"/><circle cx="185" cy="48" r="7" fill="#fff3ab"/></g>':''}</g></svg></div>`;
}
function timePrice(w){if(!state.rate)return '';const minutes=Math.round(w.price/state.rate*60);return `<span class="time-price">${icon('clock')}${Math.floor(minutes/60)}h ${minutes%60}m of work <small>· your estimate</small></span>`;}
function counterTiles(){const pending=state.wants.reduce((n,w)=>n+w.price,0);return `<div class="v-counter-grid"><button data-go="temptation-counter"><span>Temptations parked</span><strong>${money(pending)}</strong><small>${state.wants.length} saved products · undecided</small></button><button data-go="anti-haul"><span>Savings this month</span><strong>${money(skipTotal())}</strong><small>${recordedSkips().length} recorded skips · estimated savings</small></button></div>`;}
function companionHero(){const p=companionProgress();return `<section class="companion-hero"><div class="hero-kicker"><span class="chip">${icon('spark')} YOUR LITTLE PAUSE PAL</span><button class="text-link" data-go="companion">Meet me ${icon('arrow')}</button></div><div class="companion-scene"><span class="floating-token token-bag">${icon('bag')} A want can wait</span><span class="floating-token token-clock">${icon('clock')} 3 days</span><span class="companion-orbit" aria-hidden="true"></span>${mascot(p.stage,'home-pal')}<span class="scene-star star-a" aria-hidden="true">✳</span><span class="scene-star star-b" aria-hidden="true">✧</span></div><div class="hero-bottom"><div><span class="overline">${p.name}</span><h2>A little pause.<br><em>A lighter mind.</em></h2></div><button class="pal-touch" data-action="wave-pal" aria-label="Say hello to your companion">${icon('heart')}</button></div></section>`;}
function waitingItems(){const items=state.wants.filter(w=>wishFilter==='All'||w.status===wishFilter);return items.map(w=>`<button class="v-product-card ${w.status==='Ready'?'ready-product':''}" data-action="open-want" data-value="${w.id}"><div class="product-plinth"><span class="product-pill">${w.status==='Ready'?'READY TO DECIDE':'COOLING OFF'}</span><span class="product-object">${icon(w.icon)}</span><span class="product-price">${money(w.price)}</span></div><div class="product-details"><h2>${esc(w.name)}</h2>${timePrice(w)}<div class="row between"><span class="chip">${icon(w.status==='Ready'?'leaf':'clock')}${waitLabel(w)}</span><span class="round-arrow">${icon('arrow')}</span></div><p>${w.status==='Ready'?'Your decision, without the rush.':'Review '+reviewDate(w)}</p></div></button>`).join('')||`<div class="center">${mascot(0,'empty-pal')}<h2>Nothing waiting here.</h2><p class="subtitle">There is no need to fill the room.</p></div>`;}
function battleEndKey(b){const end=new Date(b.startDate+'T00:00:00');end.setDate(end.getDate()+b.days-1);return localDateKey(end);}
function battleScore(b=state.battle){if(!b)return 0;return Math.min(b.days,Object.keys(b.checkins).length);}
function battleElapsed(b=state.battle){if(!b)return 0;const start=new Date(b.startDate+'T00:00:00'),now=new Date(localDateKey()+'T00:00:00');return Math.min(b.days,Math.max(1,Math.round((now-start)/86400000)+1));}
function battleInvite(){const b=state.battle;return b?`Join my ${b.days}-day ${b.category} pause with Lessly. My rule: ${b.rule}. Essentials: ${b.exception}. We compare check-in consistency, not money. This prototype invite has no join link yet.`:'';}
function shareCardSvg(){const rows=recordedSkips(),amount=shareAmounts?money(skipTotal()):String(rows.length);const sub=shareAmounts?'in estimated savings from skipped purchases':'purchases I reconsidered';const bg=state.shareStyle==='clay'?'#f3ad91':'#183f35',fg=state.shareStyle==='clay'?'#183f35':'#fbfcf7',accent=state.shareStyle==='clay'?'#183f35':'#d2e9bd';return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><rect width="1080" height="1350" rx="56" fill="${bg}"/><circle cx="885" cy="240" r="225" fill="${accent}" opacity=".07"/><text x="90" y="130" font-family="Arial,sans-serif" font-size="48" font-weight="700" fill="${fg}">lessly / MY NO-BUY MONTH</text><text x="90" y="290" font-family="Arial,sans-serif" font-size="31" fill="${accent}">${localDateKey().slice(0,7)} · MY RECORDED CHOICES</text><text x="90" y="505" font-family="Arial,sans-serif" font-size="${Math.min(150,Math.max(28,Math.floor(900/(amount.length*.65))))}" font-weight="700" fill="${fg}">${esc(amount)}</text><text x="90" y="570" font-family="Arial,sans-serif" font-size="${shareAmounts?30:35}" fill="${accent}">${sub}</text><path d="M790 870V720m0 35c-75 0-115-75-115-75 83-12 116 50 115 75Zm0-40c75 0 115-75 115-75-83-12-116 50-115 75Z" stroke="${accent}" stroke-width="8" fill="${accent}"/><rect x="690" y="830" width="200" height="150" rx="70" fill="${accent}"/><circle cx="760" cy="884" r="9" fill="${bg}"/><circle cx="820" cy="884" r="9" fill="${bg}"/><path d="M767 914q23 22 46 0" stroke="${bg}" stroke-width="6" fill="none"/><text x="90" y="780" font-family="Arial,sans-serif" font-size="45" font-weight="700" fill="${fg}">I wanted it.</text><text x="90" y="855" font-family="Arial,sans-serif" font-size="45" font-weight="700" fill="${fg}">I paused.</text><text x="90" y="930" font-family="Arial,sans-serif" font-size="45" font-weight="700" fill="${fg}">I let it go.</text><text x="90" y="1130" font-family="Arial,sans-serif" font-size="25" fill="${accent}">${shareAmounts?'Estimated from skipped purchases. Not money set aside.':'Amounts and product details kept private.'}</text><text x="90" y="1190" font-family="Arial,sans-serif" font-size="24" fill="${accent}">Based on ${rows.length} skips recorded this month; excludes earlier totals.</text><text x="90" y="1270" font-family="Arial,sans-serif" font-size="29" font-weight="700" fill="${fg}">Want it? Wait on it.</text></svg>`;}
function viralCaption(){return `I wanted it. I paused. I let it go. ${recordedSkips().length} purchases reconsidered this month.${shareAmounts?' '+money(skipTotal())+' estimated savings from skipped purchases — not money set aside.':''} Want it? Wait on it. #NoBuy #LowBuy #AntiHaul`;}
async function copyViralText(text,filename){try{await navigator.clipboard.writeText(text);toast('Copied. Share it wherever you like.');}catch{downloadFile(filename,text,'text/plain');toast('Saved as a text file.');}}
function renderViral(id){const p=companionProgress();switch(id){
 case 'today':return `${topHome()}<div class="v-home-heading"><span class="eyebrow">YOUR SHOPPING DETOX</span><h1 class="hero-title">Want it?<br><em>Wait on it.</em></h1><span class="v-day-chip">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div>${companionHero()}<button class="v-primary-capture" data-go="add-item"><span class="capture-plus">${icon('plus')}</span><span><strong>Park a temptation</strong><small>Save a link · Wait 3 days or a week · Decide</small></span>${icon('arrow')}</button>${savingsHero()}${achievementPreview()}${counterTiles()}${readyReviewList()}<div class="v-flow-strip"><span>${icon('link')} Save</span><i></i><span>${icon('clock')} Wait</span><i></i><span>${icon('leaf')} Decide</span></div><div class="section-row"><h2 class="section-title">Keep the rhythm</h2>${link('My progress','companion')}</div><button class="daily-checkin" data-go="check-in"><span class="category-icon peach">${icon('sun')}</span><span class="grow"><strong>A tiny check-in. A little growth.</strong><span>Every thoughtful day counts.</span></span>${icon('chevron')}</button><button class="v-battle-teaser" data-go="battle-hub"><span class="mini-pal">${mascot(1,'teaser-pal')}</span><span><span class="overline">NO-BUY BATTLES</span><strong>A little friendly<br>competition.</strong><small>Your rules. Private amounts.</small></span>${icon('arrow')}</button>${listRow('This month’s anti-haul','The wants you chose to let go.','anti-haul','share')}${listRow('Actually set aside',money(state.setAside)+' confirmed outside the app · includes existing demo data','goals','wallet')}${illustratedNote('Good things, already here','Less checkout.<br>More little joys.','ritual','joy-menu')}`;
 case 'wishlist':return `${topHome()}${title('THE COOLING-OFF CLUB','Keep the want.<br><em>Lose the rush.</em>','Save it here. Your reminder brings you back in 3 days or a week.')}<button class="v-primary-capture" data-go="add-item"><span class="capture-plus">${icon('plus')}</span><span><strong>Save a product</strong><small>A link today. A choice later.</small></span>${icon('arrow')}</button><div class="v-flow-strip"><span>${icon('link')} Save</span><i></i><span>${icon('clock')} Wait</span><i></i><span>${icon('leaf')} Decide</span></div><div class="segmented">${['All','Waiting','Ready'].map(t=>`<button class="${wishFilter===t?'active':''}" data-action="filter" data-value="${t}">${t==='Ready'?'Ready to decide':t}</button>`).join('')}</div><div class="v-product-list">${waitingItems()}</div>${btn('How to save from another app','capture-guide','ghost','share')}<p class="footer-note">Starting examples are demo products. No retailer metadata is fetched.</p>`;
 case 'companion':return `${header('Your little pause pal')}${title('GROW AT YOUR OWN PACE','Small choices.<br><em>Big personality.</em>','Your companion grows with reflections, check-ins and decisions. Buying an essential never takes growth away.')}<div class="pal-feature">${mascot(p.stage,'feature-pal')}<span class="chip">${p.name} · Stage ${p.stage+1}/3</span></div><div class="card"><div class="row between"><h2 class="item-title">${p.n} thoughtful moments</h2><span class="chip">${p.next?p.next-p.n+' to next stage':'In bloom'}</span></div>${progress(p.next?p.n/p.next*100:100)}<p class="small muted" style="margin-top:12px">Completed decisions, real check-ins and recorded pauses. Saving more products adds no growth points.</p></div><div class="pal-stages">${[0,1,2].map((s,i)=>`<div class="${p.stage===s?'current':''}">${mascot(s,'stage-preview-'+s)}<b>${['Seedling','Growing','Blooming'][i]}</b><small>${[0,4,12][i]} moments</small></div>`).join('')}</div>${btn('Check in today','check-in','','sun')}${btn('Take a 90-second pause','pause','outline','pause')}<p class="footer-note">No decay, punishment or lost progress. Decorative motion can be turned off below.</p>`;
 case 'temptation-counter':return `${header('Your temptation counter')}${title('MAKE THE INVISIBLE VISIBLE','Almost bought.<br><em>Now considered.</em>','A parked product is still undecided. Only an explicit skip enters your anti-haul.')}${counterTiles()}<div class="card dark-card"><span class="overline">ESTIMATED SAVINGS</span><div class="metric">${money(skipTotal(counterPeriod))}</div><div class="segmented">${['month','all'].map(t=>`<button data-action="counter-period" data-value="${t}" class="${counterPeriod===t?'active':''}">${t==='month'?'This month':'All recorded'}</button>`).join('')}</div><p class="small">${recordedSkips(counterPeriod).length} skipped products with item history. Estimated from purchases you explicitly skipped. Money set aside is tracked separately.</p></div><div class="card">${receipt('Earlier aggregate',money(state.skippedBaseline))}<p class="small muted">Imported from the previous prototype, which includes sample data and has no item-level skip history. Excluded from new share cards.</p>${receipt('Actually set aside',money(state.setAside))}<p class="small muted">Existing demo balance plus your manual contributions. This app does not move money.</p></div>${btn('See my monthly anti-haul','anti-haul','','arrow')}${btn('Save another product','add-item','outline','plus')}`;
 case 'capture-guide':return `${header('Save from anywhere')}${title('A SHORTER PATH TO THE PAUSE','Before checkout,<br><em>send it here.</em>','The native app will appear in your phone’s Share menu. In this browser prototype, paste or import a copied link.')}<div class="native-share-preview"><div class="share-preview-product">${icon('shoe')}<strong>A product catches your eye</strong></div><div class="share-preview-row"><span>Copy link</span><span class="selected">${icon('leaf')} Lessly</span><span>Messages</span></div><span class="tiny muted">Native share-sheet design preview</span></div><ol class="capture-instructions"><li>Tap Share on the product page.</li><li>Choose Lessly and confirm the product details.</li><li>Choose 3 days or a week. Leave the decision here.</li></ol>${action('Paste a copied product link','paste-product','','link')}${btn('Enter a product manually','add-item','outline','plus')}${action('Try a demo shared product','demo-import','ghost','spark')}<p class="footer-note">Native iOS/Android sharing and device reminders need implementation. Link imports do not scrape product prices.</p>`;
 case 'buddy':case 'battle-hub':return `${header('No-Buy Battles')}${title('A FRIENDLY LITTLE CHALLENGE','Less buying.<br><em>More cheering.</em>','Challenge one friend to show up for their own rules. Compare check-in consistency, never money.')}<div class="duo-pals">${mascot(0,'buddy-one')}${mascot(1,'buddy-two')}<span>＋</span></div><div class="card mint-card"><h2>7 days or 30 days.<br>One category to pause.</h2><p class="small muted">Necessary purchases and setbacks stay part of the story. Check-ins earn credit for honest reflection.</p></div>${btn(state.battle?'Open my battle':'Create a battle',state.battle?'battle-lobby':'battle-create','','users')}${btn('Share my anti-haul','share-card','outline','share')}${btn('Quiet accountability instead','invite','ghost')}<div class="modal-note">Social flow prototype: no friend accounts, invitation delivery or live leaderboard is connected.</div>`;
 case 'battle-create':return `${header('Create a battle')}${title('YOUR RULES. THEIR RULES.','Make a little<br><em>pact.</em>','Amounts and product links stay private. Each person chooses realistic rules.')}${form('battle',field('Challenge name','name',state.battle?.name||'The seven-day pause')+select('Duration','days',['7 days','30 days'],'7 days')+select('My category','category',['Clothing','Skincare','Home','Tech','Hobbies'],'Clothing')+area('My personal rule','rule','Save new wants for three days before deciding.')+area('Essential exceptions','exception','Replace essential items that are finished, broken or unsuitable.')+submit('Create my private room','users'))}<div class="modal-note">Score = days checked in ÷ challenge duration. No purchase totals or product details are shared. Creating a new room replaces the current local room.</div>`;
 case 'battle-lobby':{const b=state.battle;if(!b)return `${header('Your battle room')}${title('START SMALL','A room for<br><em>two.</em>','Create your own rules before inviting anyone.')}${mascot(0,'feature-pal')}${btn('Create a battle','battle-create','','users')}${btn('Back to battles','battle-hub','ghost')}`;const score=battleScore(),demo=Math.min(b.days,Math.floor(b.days*.6));return `${header('Your battle room')}${title('PRIVATE ROOM · LOCAL PROTOTYPE',esc(b.name),`${battleElapsed()} of ${b.days} days elapsed. Your friend’s participation is simulated here.`)}<div class="battle-scoreboard"><div>${mascot(p.stage,'score-pal')}<b>You</b><strong>${score}/${b.days}</strong><small>${Math.round(score/b.days*100)}% check-in completion</small></div><span>vs</span><div>${mascot(1,'demo-pal')}<b>Demo opponent</b><strong>${demo}/${b.days}</strong><small>Illustrative score · not a real person</small></div></div><div class="card"><span class="overline">${esc(b.category)} · MY RULE</span><p class="small">${esc(b.rule)}</p><p class="small muted" style="margin-top:10px">Essentials: ${esc(b.exception)}</p></div>${form('battle-checkin',select('How did today go?','outcome',['Followed my plan','Necessary exception','A setback I can learn from'],'Followed my plan')+submit(b.checkins[localDateKey()]?'Update today’s check-in':'Check in today','check'))}<p class="footer-note">All three answers count as an honest check-in. One entry per day.</p>${action('Copy an invitation draft','battle-invite','outline','share')}${btn('View the recap','battle-results','ghost')}<div class="modal-note">Copying the draft sends nothing. A join link, friend consent and sync require the native backend.</div>`;}
 case 'battle-results':{const b=state.battle;return `${header('Your battle recap')}${title('EVERY HONEST DAY COUNTS','You showed up.<br><em>That matters.</em>',b?(battleElapsed()>=b.days?'The scheduled challenge period has ended.':'Live recap · Your challenge is still in progress.'):'Create a battle to begin a real local record.')}<div class="pal-feature">${mascot(p.stage,'recap-pal')}</div><div class="card mint-card"><div class="metric">${battleScore()}<span style="font-size:20px"> / ${b?.days||7}</span></div><p class="small">Recorded check-in days. No spending amounts or ranking by wealth.</p></div>${btn('Return to my battle','battle-lobby','','users')}${btn('Share my own progress','share-card','outline','share')}${btn('Try another challenge','battle-create','ghost')}`;}
 case 'anti-haul':{const rows=recordedSkips();return `${header('Your monthly anti-haul')}${title('THE THINGS YOU LET GO','Wanted it.<br>Paused. <em>Skipped it.</em>','Only explicitly skipped products recorded this month appear here.')}<div class="anti-haul-total"><span class="overline">SAVINGS THIS MONTH</span><strong>${money(skipTotal())}</strong><span>${rows.length} recorded products · estimated from skipped purchases</span></div>${rows.map(w=>`<div class="anti-haul-row"><span class="category-icon">${icon(w.icon)}</span><div class="grow"><b>${esc(w.name)}</b><small>${esc(w.category)} · ${localDateKey(w.date)}</small></div><strong>${money(w.price)}</strong></div>`).join('')||`<div class="center">${mascot(0,'empty-haul')}<h2>Your story starts with a choice.</h2><p class="subtitle">Review a saved want. If you skip it, it will appear here. Earlier demo totals are excluded.</p></div>`}${btn('Make my share card','share-card','','share')}${btn('Review my waiting room','wishlist','outline','clock')}`;}
 case 'share-card':return `${header('Share your anti-haul')}<div class="share-control"><span><b>Show my estimated savings</b><small>Private by default</small></span><button class="switch ${shareAmounts?'on':''}" role="switch" aria-checked="${shareAmounts}" aria-label="Include amounts in share card" data-action="share-amounts"></button></div><div class="share-style-picker">${[['forest','Forest'],['clay','Clay']].map(([v,l])=>`<button data-action="share-style" data-value="${v}" class="${state.shareStyle===v?'selected':''}" aria-pressed="${state.shareStyle===v}"><i class="swatch-${v}"></i>${l}</button>`).join('')}</div><div class="anti-haul-card" role="img" aria-label="Share card preview: ${recordedSkips().length} recorded skipped purchases this month">${shareCardSvg()}</div>${action('Download my share card','download-card','','download')}${action('Copy my caption','copy-caption','outline','share')}<p class="footer-note">Product names, links, personal notes and actual savings balances are excluded. Amounts reflect recorded skips only, with earlier sample totals excluded.</p>`;
 case 'achievements':return `${header('Savings & achievements')}${title('EVERY LITTLE WIN COUNTS','Less impulse.<br><em>More achievement.</em>','Your badges grow with recorded skips and honest check-ins. Purchases never remove an earned milestone.')}<div class="achievement-summary"><span class="achievement-medal">${icon('spark')}</span><div><strong>${achievementDefinitions().filter(a=>a.value>=a.goal).length}<small> / ${achievementDefinitions().length}</small></strong><span>achievements unlocked</span></div></div><div class="achievement-grid">${achievementCards()}</div><p class="footer-note">Savings milestones use estimated cost from recorded skips. Earlier demo totals never unlock badges. Check-ins need not be consecutive.</p>${btn('Share my monthly wins','share-card','','share')}${btn('Review my waiting room','wishlist','outline','clock')}`;
 case 'skip-done':return `${header('A little win')}<div class="pal-feature celebration">${mascot(p.stage,'celebration-pal')}<span class="chip">One thoughtful decision recorded</span></div>${title('WANT → WAIT → DECIDE','You wanted it.<br><em>You let it go.</em>','Your companion keeps growing. There is no need to buy anything to celebrate.')}<div class="card mint-card"><span class="overline">YOU SAVED AN ESTIMATED</span><div class="metric">${money(draft.skippedPrice||0)}</div><p class="small muted">By skipping this purchase. Money actually set aside stays separate.</p></div>${(draft.earnedAchievements||[]).map(name=>`<div class="achievement-unlock-banner">${icon('spark')}<span><small>ACHIEVEMENT UNLOCKED</small><b>${esc(name)}</b></span></div>`).join('')}${btn('See my achievements','achievements','outline','spark')}${btn('Add this win to my share card','share-card','','share')}${btn('I actually set money aside','set-aside','outline','wallet')}${btn('Back to Today','today','ghost')}`;
 default:return null;
}}
function handleViralAction(name,value){switch(name){
 case 'wave-pal':{const el=document.querySelector('.home-pal');el?.classList.add('pal-wave');toast('A little pause is a lovely start.');setTimeout(()=>el?.classList.remove('pal-wave'),900);return true;}
 case 'counter-period':if(['all','month'].includes(value)){counterPeriod=value;render();}return true;
 case 'share-style':if(['forest','clay'].includes(value)){state.shareStyle=value;persist();render();}return true;
 case 'demo-import':draft.newWantUrl='https://shop.example.com/products/everyday-sneakers';draft.newWantName='Demo everyday sneakers';draft.newWantPrice='';go('add-item');toast('Demo link imported. Enter the actual price yourself.');return true;
 case 'paste-product':pasteProductLink();return true;
 case 'battle-invite':copyViralText(battleInvite(),'lessly-invitation.txt');return true;
 default:return false;
}}
async function pasteProductLink(){try{const text=await navigator.clipboard.readText(),url=safeProductUrl(text);if(!url){toast('Copy an http or https product link first.');return;}draft.newWantUrl=url;go('add-item');toast('Link pasted. Confirm the name, price and reminder.');}catch{go('add-item');toast('Paste your copied link in the product field.');}}
function handleViralForm(id,data,error,required){switch(id){
 case 'battle':{if(!required('name','A challenge name')||!required('rule','A personal rule')||!required('exception','An essential exception'))return true;const days=parseInt(data.days);if(![7,30].includes(days)||!['Clothing','Skincare','Home','Tech','Hobbies'].includes(data.category)){error('Choose a supported duration and category.','days');return true;}state.battle={id:newRecordId(),name:data.name.trim(),days,category:data.category,rule:data.rule.trim(),exception:data.exception.trim(),startDate:localDateKey(),checkins:{}};persist();go('battle-lobby');return true;}
 case 'battle-checkin':{const b=state.battle;if(!b){go('battle-create');return true;}if(localDateKey()>battleEndKey(b)){error('This challenge has ended. You can start another.','outcome');return true;}if(!['Followed my plan','Necessary exception','A setback I can learn from'].includes(data.outcome)){error('Choose how today went.','outcome');return true;}b.checkins[localDateKey()]={outcome:data.outcome};recordViralCheckin();persist();go('battle-lobby');toast('Your honest check-in counts. Progress stays.');return true;}
 default:return false;
}}
function importSharedProduct(){try{const params=new URL('https://lessly.local/'+(location.search||'')).searchParams;const raw=params.get('url')||(params.get('text')||'').match(/https?:\/\/[^\s]+/)?.[0];if(!raw)return;const safe=safeProductUrl(raw);if(!safe)return;draft.newWantUrl=safe;draft.newWantName=(params.get('title')||'').slice(0,180);screen='add-item';}catch{}}
